def solve(task, env):
    schema = env.schema(task["db_id"])
    env_schema_cache["schema"] = schema
    user = f"Database: {task['db_id']}\n\nSchema:\n{schema}\n\nQuestion: {task['question']}"
    desc = ""
    try:
        desc = env.descriptions(task["db_id"]) or ""
    except Exception:
        desc = ""
    if desc:
        user += f"\n\nColumn descriptions:\n{desc[:3000]}"
    if task.get("hint"):
        user += f"\nHint: {task['hint']}"

    messages = [
        {"role": "system", "content": env.prompt("system_prompt.md")},
        {"role": "user", "content": user},
    ]
    reply = env.chat(messages, max_tokens=env.config.get("max_tokens", 800))
    sql = extract_sql(reply)

    res = env.execute(sql)
    needs_repair = (not res.get("ok")) or res.get("n_rows", 0) == 0

    if not needs_repair:
        return {"sql": sql}

    feedback = _fmt_result(res)
    if res.get("ok") and res.get("n_rows", 0) == 0:
        probes = _probe_literals(sql, env)
        if probes:
            feedback += "\n\nLiteral lookup results:\n" + probes

    repair_user = (
        f"Your previous query:\n```sql\n{sql}\n```\n\n"
        f"Execution feedback:\n{feedback}\n\n"
        "If the query errored, fix the error. If it returned 0 rows, the filter values likely do not "
        "match stored data: use the literal lookup results above, or relax to case-insensitive "
        "LIKE '%...%' matching with trimmed whitespace. Also re-check that the selected columns "
        "match what the question asks (all columns when it asks for details/everything about entities). "
        "Return the corrected query in a single ```sql code block."
    )
    messages2 = messages + [
        {"role": "assistant", "content": reply},
        {"role": "user", "content": repair_user},
    ]
    try:
        reply2 = env.chat(messages2, max_tokens=env.config.get("max_tokens", 800))
    except Exception:
        return {"sql": sql}
    sql2 = extract_sql(reply2)
    if not sql2:
        return {"sql": sql}
    res2 = env.execute(sql2)
    # prefer the repaired query if it runs and returns rows, or if original errored
    if res2.get("ok") and (res2.get("n_rows", 0) > 0 or not res.get("ok")):
        return {"sql": sql2}
    if res.get("ok"):
        return {"sql": sql}
    return {"sql": sql2}

